#### 2. 区域截图函数

**文件**: `src/lib/screenshot.ts`

```typescript
import { invoke } from '@tauri-apps/api/core'
import type { CustomRegion } from './settings'

// ... existing interfaces and functions ...

/**
 * Region screenshot parameters
 */
export interface RegionScreenshotParams {
  x: number
  y: number
  width: number
  height: number
}

/**
 * Take a region screenshot using native screen capture (xcap)
 */
export async function takeRegionScreenshot(
  region: RegionScreenshotParams
): Promise<ScreenshotResult> {
  try {
    const result = await invoke<ScreenshotBackendResult>('capture_screen_region', {
      x: region.x,
      y: region.y,
      width: region.width,
      height: region.height
    })

    if (!result.success) {
      throw new Error(result.error || 'Region screenshot failed')
    }

    return {
      success: true,
      path: result.path
    }
  } catch (error) {
    console.error('Region screenshot failed:', error)
    return {
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error'
    }
  }
}

/**
 * Take region screenshot and automatically download
 */
export async function takeAndDownloadRegionScreenshot(
  region?: RegionScreenshotParams
): Promise<void> {
  // If no region provided, use default centered region
  // The backend will calculate it based on monitor size
  const finalRegion = region || await getDefaultRegion()

  const result = await takeRegionScreenshot(finalRegion)

  if (!result.success) {
    throw new Error(result.error || 'Region screenshot failed')
  }

  console.log('Region screenshot saved to:', result.path)
}

/**
 * Get default centered region based on monitor size
 * This is a placeholder - actual calculation happens in Rust backend
 */
async function getDefaultRegion(): Promise<RegionScreenshotParams> {
  // Default to medium preset (800x600 centered)
  // The backend will adjust based on actual monitor size
  return {
    x: 0,  // Will be centered by backend
    y: 0,  // Will be centered by backend
    width: 800,
    height: 600
  }
}

/**
 * Update screenshot capabilities to include region capture
 */
export function getScreenshotCapabilities() {
  return {
    supported: true,
    formats: ['png'] as const,
    nativeCapture: true,
    regionCapture: true  // 新增
  }
}
```

#### 3. 快捷键系统扩展

**文件**: `src/lib/shortcuts.ts`

```typescript
import { register, unregister, isRegistered } from '@tauri-apps/plugin-global-shortcut'

// Currently registered shortcuts
let currentScreenshotShortcut: string | null = null
let currentRegionCaptureShortcut: string | null = null  // 新增

// ... existing convertToTauriFormat function ...

/**
 * Register region capture shortcut
 */
export async function registerRegionCaptureShortcut(shortcut: string): Promise<void> {
  if (!shortcut || shortcut.trim() === '') {
    throw new Error('Shortcut cannot be empty')
  }

  // Check for conflict with screenshot shortcut
  if (shortcut === currentScreenshotShortcut) {
    throw new Error('Region capture shortcut conflicts with screenshot shortcut')
  }

  console.log(`Attempting to register region capture shortcut: ${shortcut}`)

  try {
    // Unregister current region shortcut if exists
    if (currentRegionCaptureShortcut) {
      console.log(`Unregistering current region shortcut: ${currentRegionCaptureShortcut}`)
      await unregisterRegionCaptureShortcut()
    }

    const tauriShortcut = convertToTauriFormat(shortcut)
    console.log(`Converted region shortcut format: ${tauriShortcut}`)

    // Check if shortcut is already registered
    const alreadyRegistered = await isRegistered(tauriShortcut)
    if (alreadyRegistered) {
      throw new Error('Shortcut is already in use by another application')
    }

    // Register new shortcut
    await register(tauriShortcut, () => {
      console.log(`Region capture shortcut ${tauriShortcut} triggered!`)
      handleRegionScreenshotTrigger()
    })

    currentRegionCaptureShortcut = shortcut
    console.log(`Region capture shortcut registered successfully: ${shortcut}`)
  } catch (error) {
    console.error('Failed to register region capture shortcut:', error)
    throw new Error('Failed to register region capture shortcut')
  }
}

/**
 * Unregister region capture shortcut
 */
export async function unregisterRegionCaptureShortcut(): Promise<void> {
  if (!currentRegionCaptureShortcut) {
    return
  }

  try {
    const tauriShortcut = convertToTauriFormat(currentRegionCaptureShortcut)
    await unregister(tauriShortcut)
    console.log(`Region capture shortcut unregistered: ${currentRegionCaptureShortcut}`)
    currentRegionCaptureShortcut = null
  } catch (error) {
    console.error('Failed to unregister region capture shortcut:', error)
    currentRegionCaptureShortcut = null
  }
}

/**
 * Handle region screenshot trigger
 */
function handleRegionScreenshotTrigger(): void {
  console.log('Region screenshot shortcut triggered!')

  // Import screenshot and settings functions dynamically
  Promise.all([
    import('@/lib/screenshot'),
    import('@/lib/settings')
  ]).then(([{ takeAndDownloadRegionScreenshot }, { loadSettings, REGION_PRESETS }]) => {
    // Load settings to get region configuration
    loadSettings().then(settings => {
      let region: any = undefined

      if (settings.regionCapture?.enabled) {
        if (settings.regionCapture.custom) {
          // Use custom region
          region = settings.regionCapture.custom
        } else if (settings.regionCapture.preset) {
          // Use preset region (will be centered by backend)
          const presetSize = REGION_PRESETS[settings.regionCapture.preset]
          region = {
            x: 0,  // Will be centered by backend
            y: 0,
            ...presetSize
          }
        }
      }

      // Take region screenshot
      takeAndDownloadRegionScreenshot(region)
        .then(() => {
          console.log('Region screenshot taken successfully')
          import('sonner').then(({ toast }) => {
            toast.success('区域截图已保存')
          }).catch(() => {
            console.log('Region screenshot saved successfully')
          })
        })
        .catch((error) => {
          console.error('Region screenshot failed:', error)
          import('sonner').then(({ toast }) => {
            toast.error('区域截图失败')
          }).catch(() => {
            console.error('Region screenshot failed')
          })
        })
    }).catch(error => {
      console.error('Failed to load settings:', error)
    })
  }).catch((error) => {
    console.error('Failed to load screenshot module:', error)
  })
}

/**
 * Initialize shortcuts on app startup (extended)
 */
export async function initializeShortcuts(
  screenshotShortcut?: string,
  regionCaptureShortcut?: string  // 新增参数
): Promise<void> {
  try {
    if (screenshotShortcut && screenshotShortcut.trim() !== '') {
      await registerScreenshotShortcut(screenshotShortcut)
    }
    if (regionCaptureShortcut && regionCaptureShortcut.trim() !== '') {
      await registerRegionCaptureShortcut(regionCaptureShortcut)
    }
  } catch (error) {
    console.error('Failed to initialize shortcuts:', error)
  }
}

/**
 * Cleanup shortcuts on app shutdown (extended)
 */
export async function cleanupShortcuts(): Promise<void> {
  try {
    await unregisterScreenshotShortcut()
    await unregisterRegionCaptureShortcut()  // 新增
  } catch (error) {
    console.error('Failed to cleanup shortcuts:', error)
  }
}

// ... existing functions remain unchanged ...
