```typescript
import { useState } from 'react'
import { type Locale, useTranslation } from '@/lib/i18n'
import { type RegionCaptureConfig, type RegionPreset, REGION_PRESETS } from '@/lib/settings'
import { cn } from '@/lib/utils'

interface RegionCaptureSectionProps {
  locale: Locale
  shortcut: string
  onShortcutChange: (shortcut: string) => void
  config?: RegionCaptureConfig
  onConfigChange: (config: RegionCaptureConfig) => void
}

export function RegionCaptureSection({
  locale,
  shortcut,
  onShortcutChange,
  config,
  onConfigChange
}: RegionCaptureSectionProps) {
  const t = useTranslation(locale)
  const [showAdvanced, setShowAdvanced] = useState(false)

  const handlePresetChange = (preset: RegionPreset) => {
    onConfigChange({
      ...config,
      enabled: true,
      preset,
      custom: undefined
    })
  }

  const handleCustomRegion = (field: string, value: number) => {
    const custom = config?.custom || { x: 0, y: 0, width: 800, height: 600 }
    onConfigChange({
      ...config,
      enabled: true,
      preset: undefined,
      custom: { ...custom, [field]: value }
    })
  }

  return (
    <div className="space-y-3">
      <h3 className="text-sm font-medium text-foreground">
        区域截图
      </h3>

      {/* Shortcut Input */}
      <div className="space-y-2">
        <label className="text-xs text-muted-foreground">快捷键</label>
        <input
          type="text"
          value={shortcut}
          readOnly
          className="w-full px-3 py-2 text-sm rounded-md border border-input bg-background"
        />
      </div>

      {/* Preset Selection */}
      <div className="space-y-2">
        <label className="text-xs text-muted-foreground">区域大小</label>
        <div className="grid grid-cols-3 gap-2">
          {(['small', 'medium', 'large'] as RegionPreset[]).map(preset => (
            <button
              key={preset}
              onClick={() => handlePresetChange(preset)}
              className={cn(
                "px-3 py-2 text-sm rounded-md border transition-colors",
                config?.preset === preset
                  ? "bg-primary text-primary-foreground border-primary"
                  : "bg-background border-input hover:bg-accent"
              )}
            >
              {preset === 'small' && '小 (400×300)'}
              {preset === 'medium' && '中 (800×600)'}
              {preset === 'large' && '大 (1280×720)'}
            </button>
          ))}
        </div>
      </div>

      {/* Advanced Configuration */}
      <div className="space-y-2">
        <button
          onClick={() => setShowAdvanced(!showAdvanced)}
          className="text-xs text-muted-foreground hover:text-foreground transition-colors"
        >
          {showAdvanced ? '▼' : '▶'} 高级配置
        </button>

        {showAdvanced && (
          <div className="grid grid-cols-2 gap-2 pt-2">
            <div>
              <label className="text-xs text-muted-foreground">X坐标</label>
              <input
                type="number"
                value={config?.custom?.x || 0}
                onChange={(e) => handleCustomRegion('x', parseInt(e.target.value))}
                className="w-full px-2 py-1 text-sm rounded border border-input"
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">Y坐标</label>
              <input
                type="number"
                value={config?.custom?.y || 0}
                onChange={(e) => handleCustomRegion('y', parseInt(e.target.value))}
                className="w-full px-2 py-1 text-sm rounded border border-input"
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">宽度</label>
              <input
                type="number"
                value={config?.custom?.width || 800}
                onChange={(e) => handleCustomRegion('width', parseInt(e.target.value))}
                className="w-full px-2 py-1 text-sm rounded border border-input"
              />
            </div>
            <div>
              <label className="text-xs text-muted-foreground">高度</label>
              <input
                type="number"
                value={config?.custom?.height || 600}
                onChange={(e) => handleCustomRegion('height', parseInt(e.target.value))}
                className="w-full px-2 py-1 text-sm rounded border border-input"
              />
            </div>
          </div>
        )}
      </div>
    </div>
  )
}
